// Nebula — realtime sync room.
//
// One Durable Object per shared room. The room id (from `idFromName`) IS the
// share secret: it is an unguessable token generated by the client, so anyone
// holding the link can read and write. This is deliberate — it is a two-person
// share, not access control. See sync/README.md for the trade-off.
//
// Extends YDurableObjects (y-durableobjects), which already:
//   - loads the persisted doc in onStart() (survives hibernation + eviction)
//   - persists on every update via doc.on("update") -> storage.storeUpdate()
//   - uses the hibernation WebSocket API, so an idle room is not billed
//   - speaks the y-protocols sync/awareness wire format
//
// What this subclass adds:
//   - room hygiene: an abandoned room's storage is deleted after IDLE_DELETE_DAYS,
//     so the free tier's 5 GB storage does not fill with rooms nobody opened.
//   - it never deletes a room while a socket is still attached.

import { YDurableObjects } from 'y-durableobjects';

const DEFAULT_IDLE_DAYS = 30;

export class NebulaRoom extends YDurableObjects {
  /**
   * `onStart` runs inside `blockConcurrencyWhile`, once, before any request.
   * Restore the alarm so an abandoned room still gets reaped after eviction.
   */
  async onStart() {
    await super.onStart();

    const idleDays = Number(this.env?.IDLE_DELETE_DAYS) || DEFAULT_IDLE_DAYS;
    const idleMs = Math.max(1, idleDays) * 24 * 60 * 60 * 1000;

    this._idleMs = idleMs;
    this._lastActive = Number((await this.ctx.storage.get('lastActive')) || 0);

    // Only arm the alarm when the room is genuinely idle — otherwise an active
    // room would keep rescheduling itself forever.
    if (this._lastActive === 0 || Date.now() - this._lastActive > idleMs) {
      this._armAlarm();
    }
  }

  /** Bump activity and push the reap alarm out. */
  async webSocketMessage(ws, message) {
    this._touch();
    return super.webSocketMessage(ws, message);
  }

  async webSocketClose(ws, code, reason, wasClean) {
    const res = await super.webSocketClose(ws, code, reason, wasClean);
    this._armAlarm();
    return res;
  }

  /**
   * Reap an abandoned room. Never runs while a client is attached, and only
   * when the room has been untouched for the full idle window.
   */
  async alarm() {
    const attached = this.ctx.getWebSockets().length;
    if (attached > 0) {
      this._touch();
      this._armAlarm();
      return;
    }

    const idleMs = this._idleMs || DEFAULT_IDLE_DAYS * 24 * 60 * 60 * 1000;
    const lastActive = Number((await this.ctx.storage.get('lastActive')) || 0);

    if (lastActive !== 0 && Date.now() - lastActive < idleMs) {
      this._armAlarm();
      return;
    }

    // Abandoned: drop everything. A later visit starts an empty room.
    await this.ctx.storage.deleteAll();
    this._lastActive = 0;
  }

  /** Record activity. Cheap: one small write per message batch, not per keystroke. */
  _touch() {
    const now = Date.now();
    if (now - this._lastActive < 60 * 1000) return;
    this._lastActive = now;
    this.ctx.storage.put('lastActive', now).catch(() => {});
  }

  _armAlarm() {
    const idleMs = this._idleMs || DEFAULT_IDLE_DAYS * 24 * 60 * 60 * 1000;
    this.ctx.storage.setAlarm(Date.now() + idleMs).catch(() => {});
  }
}
